using Microsoft.EntityFrameworkCore;

public class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public decimal Price { get; set; }
    public bool IsActive { get; set; }
}

public class AppDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseSqlServer(
            "Server=.;Database=ShopDb;Trusted_Connection=True;TrustServerCertificate=True;");
}

using var context = new AppDbContext();

var cheapProducts = await context.Products
    .Where(p => p.IsActive && p.Price < 50)
    .OrderBy(p => p.Name)
    .Select(p => new { p.Name, p.Price })
    .ToListAsync();

foreach (var p in cheapProducts)
{
    Console.WriteLine($"{p.Name}: {p.Price:C}");
}

using var context = new AppDbContext();

// CREATE
var newProduct = new Product { Name = "Laptop", Price = 999.99m, IsActive = true };
context.Products.Add(newProduct);
await context.SaveChangesAsync();
Console.WriteLine($"Added product with Id: {newProduct.Id}");

// READ
var product = await context.Products.FirstOrDefaultAsync(p => p.Name == "Laptop");
Console.WriteLine($"Found: {product?.Name} at {product?.Price:C}");

// UPDATE
if (product != null)
{
    product.Price = 899.99m;
    await context.SaveChangesAsync();
    Console.WriteLine("Price updated.");
}

// DELETE
if (product != null)
{
    context.Products.Remove(product);
    await context.SaveChangesAsync();
    Console.WriteLine("Product deleted.");
}
